export async function setIssueAssignee(
  orgId: OrgId,
  issueId: IssueId,
  assigneeId: UserId | null,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({ assigneeId, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);
  return toIssue(row);
}

/** Live issues owned by a member, used when their organization membership ends. */
export async function listLiveIssuesAssignedTo(
  orgId: OrgId,
  assigneeId: UserId,
): Promise<Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.assigneeId, assigneeId),
        isNull(issues.archivedAt),
      ),
    )
    .all();

  return rows.map(toIssue);
}

export async function archiveIssue(
  orgId: OrgId,
